{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, min(value) AS mn, max(value) AS mx, count(*) AS n FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'recommendation%' AND metric IN ('k8s.container.ready','k8s.container.restarts') GROUP BY 1,2",
          "claim": "Recommendation pod container never ready in the abnormal window; restarts climb to 2-6, versus 1 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n FROM abnormal_traces WHERE service_name = 'recommendation' GROUP BY ALL",
          "claim": "Recommendation emits no spans in the abnormal window, though it had 115 in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, round(avg(value),3) AS avg_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'recommendation%' AND metric IN ('container.memory.working_set','container.cpu.usage') GROUP BY 1,2",
          "claim": "Recommendation memory and CPU stay at normal levels, so the restarts are not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_http_response_status_code AS code, attr_status_code, count(*) AS n FROM abnormal_traces WHERE attr_status_code = 'Error' GROUP BY ALL ORDER BY n DESC",
          "claim": "All 171 abnormal errors are frontend GetRecommendations client calls turning into HTTP /recommendations 500 responses."
        }
      ]
    }
  ]
}
